"""OpenTruck - J1939 parameter lookup tables.

SPN (Suspect Parameter Number) names and FMI (Failure Mode Identifier)
descriptions are standardized by SAE J1939-71 / J1939-73. SPN numbers and their
short names are standardized facts used industry-wide; the table below maps
them to their canonical short names, supplemented with hand-curated,
field-verified entries from our own on-truck testing. A small number of
ISOBUS-only SPN numbers (e.g. 5233/5235 in the implement/tractor range) appear
in more than one registry; the first published name is kept for those.
"""

# Failure Mode Identifier (J1939-73). These 0..31 values are standardized.
FMI = {
    0:  "Data valid but above normal range - most severe",
    1:  "Data valid but below normal range - most severe",
    2:  "Data erratic, intermittent or incorrect",
    3:  "Voltage above normal / shorted high",
    4:  "Voltage below normal / shorted low",
    5:  "Current below normal / open circuit",
    6:  "Current above normal / grounded circuit",
    7:  "Mechanical system not responding or out of adjustment",
    8:  "Abnormal frequency or pulse width or period",
    9:  "Abnormal update rate",
    10: "Abnormal rate of change",
    11: "Root cause not known",
    12: "Bad intelligent device or component",
    13: "Out of calibration",
    14: "Special instructions",
    15: "Data valid but above normal range - least severe",
    16: "Data valid but above normal range - moderately severe",
    17: "Data valid but below normal range - least severe",
    18: "Data valid but below normal range - moderately severe",
    19: "Received network data in error",
    20: "Data drifted high",
    21: "Data drifted low",
    31: "Condition exists",
}


def fmi_name(fmi: int) -> str:
    return FMI.get(fmi, f"FMI {fmi} (spare/reserved)")

