def spn_name(spn: int) -> str | None:
    """SPN name from the SAE table, or ``None`` when the SPN is unknown."""
    return SPN_NAMES.get(spn)


# Shown when a fault code can't be resolved to a real name anywhere (no OEM
# override and no generic SAE entry). The numeric SPN/PID/SID and FMI are still
# shown in their own columns, so this tells the tech "look it up at the OEM"
# rather than printing a wrong-looking placeholder or a bare code number.
UNRESOLVED_CODE = "Refer to OEM"


# NOTE: OEM- and component-specific SPN overrides, plus the context-aware
# ``resolve_code_description`` helper, live in ``oem.py`` so the generic SAE
# table here stays uncontaminated by any one manufacturer's private numbering.
